#define BILI_DOWNLOAD_TEST
#include "../src/main.cpp"
#include <iostream>
void dumpTrack(const fs::path& file,DWORD stream,const fs::path& out){MediaCom<IMFAttributes> attr;mediaCheck(MFCreateAttributes(attr.out(),1));mediaCheck(attr->SetUINT32(MF_READWRITE_DISABLE_CONVERTERS,TRUE));MediaCom<IMFSourceReader> reader;mediaCheck(MFCreateSourceReaderFromURL(file.c_str(),attr.p,reader.out()));mediaCheck(reader->SetStreamSelection(MF_SOURCE_READER_ALL_STREAMS,FALSE));mediaCheck(reader->SetStreamSelection(stream,TRUE));MediaCom<IMFMediaType> type;mediaCheck(reader->GetNativeMediaType(stream,0,type.out()));mediaCheck(reader->SetCurrentMediaType(stream,nullptr,type.p));std::ofstream bytes(out,std::ios::binary);unsigned count=0;LONGLONG last=0;while(true){DWORD flags;LONGLONG time;MediaCom<IMFSample> sample;mediaCheck(reader->ReadSample(stream,0,nullptr,&flags,&time,sample.out()));if(sample.p){MediaCom<IMFMediaBuffer> buffer;mediaCheck(sample->ConvertToContiguousBuffer(buffer.out()));BYTE* ptr;DWORD size;mediaCheck(buffer->Lock(&ptr,nullptr,&size));bytes.write((char*)ptr,size);buffer->Unlock();count++;last=time;}if(flags&MF_SOURCE_READERF_ENDOFSTREAM)break;}std::cout<<count<<" "<<last<<"\n";}
int wmain(int argc,wchar_t** argv){try{if(argc==5){runDownloadPlan(argv[1],argv[2],fs::path(argv[3]));return 0;}if(argc==3){mediaCheck(CoInitializeEx(nullptr,COINIT_MULTITHREADED));mediaCheck(MFStartup(MF_VERSION));dumpTrack(argv[1],MF_SOURCE_READER_FIRST_VIDEO_STREAM,fs::path(std::wstring(argv[2])+L".v.es"));dumpTrack(argv[1],MF_SOURCE_READER_FIRST_AUDIO_STREAM,fs::path(std::wstring(argv[2])+L".a.es"));MFShutdown();CoUninitialize();return 0;}return 2;}catch(const std::exception& e){std::cerr<<e.what();return 1;}}
